// composables/useMouse.ts
import { ref, onMounted, onUnmounted, readonly } from "vue";

export function useMouse() {
  const x = ref(0);
  const y = ref(0);

  function update(event: MouseEvent) {
    x.value = event.clientX;
    y.value = event.clientY;
  }

  onMounted(() => window.addEventListener("mousemove", update));
  onUnmounted(() => window.removeEventListener("mousemove", update));

  // Return readonly refs so consumers can't mutate
  return { x: readonly(x), y: readonly(y) };
}

// router/index.ts
import { createRouter, createWebHistory } from "vue-router";
import Home from "@/views/Home.vue";
import About from "@/views/About.vue";

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    { path: "/", name: "home", component: Home },
    { path: "/about", name: "about", component: About },
    {
      path: "/user/:id",
      name: "user",
      component: () => import("@/views/User.vue"),
      props: true,  // pass :id as a prop
    },
  ],
});

export default router;

// stores/counter.ts
import { ref, computed } from "vue";
import { defineStore } from "pinia";

export const useCounterStore = defineStore("counter", () => {
  const count = ref(0);
  const double = computed(() => count.value * 2);

  function increment() {
    count.value++;
  }

  async function incrementAsync() {
    await new Promise((r) => setTimeout(r, 100));
    count.value++;
  }

  return { count, double, increment, incrementAsync };
});

// tests/unit/Counter.spec.ts
import { describe, it, expect } from "vitest";
import { mount } from "@vue/test-utils";
import Counter from "@/components/Counter.vue";

describe("Counter.vue", () => {
  it("renders initial count", () => {
    const wrapper = mount(Counter, { props: { initial: 5 } });
    expect(wrapper.text()).toContain("5");
  });

  it("emits increment on button click", async () => {
    const wrapper = mount(Counter);
    await wrapper.get("button").trigger("click");
    expect(wrapper.emitted("increment")).toHaveLength(1);
    expect(wrapper.emitted("increment")![0]).toEqual([1]);
  });
});
